cd <local-root>/ttl-cache && cat > test_comprehensive.mjs << 'EOF'
import * as m from './impl.mjs';

// Test basic functionality
let t = 0;
const c = m.createCache({now: () => t, ttlMs: 10});

// Test set and get
c.set('a', 2);
assert.equal(c.get('a'), 2);

// Test expiration
t = 10;
assert.equal(c.get('a'), undefined);

// Test that size excludes expired entries
assert.equal(c.size(), 0);

// Test with multiple entries
t = 0;
c.set('a', 1);
c.set('b', 2);
assert.equal(c.get('a'), 1);
assert.equal(c.get('b'), 2);
assert.equal(c.size(), 2);

// Test TTL reset on set
t = 5;
c.set('a', 3); // This should reset the TTL
assert.equal(c.get('a'), 3);
t = 15; // Should still be valid since we reset the TTL
assert.equal(c.get('a'), 3);
t = 20; // Now it should expire
assert.equal(c.get('a'), undefined);

// Test delete functionality
t = 0;
c.set('x', 'value');
assert.equal(c.delete('x'), true);
assert.equal(c.get('x'), undefined);
assert.equal(c.size(), 0);

// Test delete on already expired entry
t = 0;
c.set('y', 'value');
t = 15;
assert.equal(c.delete('y'), false); // Should return false for expired entry
assert.equal(c.size(), 0);

// Test with objects as keys
t = 0;
const keyObj = { id: 1 };
c.set(keyObj, 'obj-value');
assert.equal(c.get(keyObj), 'obj-value');

// Test with undefined values
t = 0;
c.set('undefined-value', undefined);
assert.equal(c.get('undefined-value'), undefined);
assert.equal(c.size(), 1);

console.log('All tests passed!');
EOF

